abstract final class EnglishAdvancedA2UnitTwoLast {
  static const lessons=<EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:8,title:"The Lost Phone",titleArabic:"الهاتف المفقود",storyTitle:"The Lost Phone",storyTitleArabic:"الهاتف المفقود",paragraphs:<String>["Lina was waiting near the bus stop when she realized that her phone was gone. She checked her jacket pocket and searched her bag, but the phone case was empty. She tried to remember the last time she had looked at the screen.","With a friend, she decided to retrace her steps and ask the lost property office for help. An officer asked about the ringtone and lock screen, then helped her complete a report form.","Later, a driver heard a notification and returned the phone. Lina thanked him and saved a backup contact number at home. She decided to take better care of her things on future journeys."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("jacket pocket","جيب سترة"),EnglishAdvancedWord("phone case","غطاء هاتف"),EnglishAdvancedWord("screen","شاشة"),EnglishAdvancedWord("retrace","يتتبع"),EnglishAdvancedWord("lost property","مكتب مفقودات"),EnglishAdvancedWord("ringtone","نغمة رنين"),EnglishAdvancedWord("lock screen","شاشة قفل"),EnglishAdvancedWord("report form","نموذج بلاغ"),EnglishAdvancedWord("driver","سائق"),EnglishAdvancedWord("notification","إشعار"),EnglishAdvancedWord("backup","احتياطي"),EnglishAdvancedWord("contact number","رقم اتصال")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("device password","كلمة مرور جهاز"),EnglishAdvancedWord("charging cable","سلك شحن"),EnglishAdvancedWord("power bank","شاحن متنقل"),EnglishAdvancedWord("screen protector","حامي شاشة"),EnglishAdvancedWord("location sharing","مشاركة الموقع"),EnglishAdvancedWord("missed call","مكالمة فائتة"),EnglishAdvancedWord("call history","سجل مكالمات"),EnglishAdvancedWord("unlock code","رمز فتح"),EnglishAdvancedWord("battery indicator","مؤشر بطارية"),EnglishAdvancedWord("telephone directory","دليل الهاتف"),EnglishAdvancedWord("emergency dial","اتصال طوارئ"),EnglishAdvancedWord("data backup","نسخة بيانات احتياطية")],grammarTitle:"Defining relative clauses",grammarArabic:"نستخدم who للأشخاص وwhich للأشياء وthat لكليهما في جملة صلة محددة، مثل the driver who found my phone.",grammarExamples:<String>["The driver who found the phone was kind.","This is the phone that I lost.","The officer who helped me was patient."],listening:"If you lose your phone on a bus, please contact the lost property office. You will need to give the route number, date and a description of the device. We may ask about your lock screen to confirm ownership. Found items are usually stored for thirty days. Wait for a confirmation message before visiting, because not every missing item is returned.",listeningQuestion:"What does the office ask for?",listeningOptions:<String>["Route, date and device description","Favorite food","School grades"],listeningAnswer:0,readingQuestion:"How did Lina get her phone back?",readingOptions:<String>["A driver returned it","She bought another phone","She found it at home"],readingAnswer:0,writingCue:"The driver heard a ____ from the missing phone.",writingAnswer:"notification"),
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:9,title:"Buying a Birthday Gift",titleArabic:"شراء هدية عيد ميلاد",storyTitle:"Buying a Birthday Gift",storyTitleArabic:"شراء هدية عيد ميلاد",paragraphs:<String>["Tariq visited a craft fair to find a birthday gift for his sister. He liked a handmade ceramic mug at a colorful stall. The shop assistant said it could be personalized with his sister's initials.","He checked the price tag and his wallet before making a choice. The assistant engraved the initials, placed the mug in a gift box, and tied a ribbon around the lid.","At the birthday party, his sister opened the box and smiled. Tariq felt proud because the small handmade present showed how carefully he had thought about her interests."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("craft fair","سوق حرفي"),EnglishAdvancedWord("birthday gift","هدية عيد ميلاد"),EnglishAdvancedWord("handmade","صنع يدوي"),EnglishAdvancedWord("ceramic mug","كوب خزفي"),EnglishAdvancedWord("stall","كشك"),EnglishAdvancedWord("shop assistant","مساعد متجر"),EnglishAdvancedWord("personalized","مخصص"),EnglishAdvancedWord("initials","حروف الاسم الأولى"),EnglishAdvancedWord("price tag","بطاقة سعر"),EnglishAdvancedWord("wallet","محفظة"),EnglishAdvancedWord("engraved","نقش"),EnglishAdvancedWord("ribbon","شريط زينة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("gift card","بطاقة هدية"),EnglishAdvancedWord("gift tissue","ورق تغليف رقيق"),EnglishAdvancedWord("keepsake","تذكار"),EnglishAdvancedWord("handicraft","صنعة يدوية"),EnglishAdvancedWord("custom order","طلب مخصص"),EnglishAdvancedWord("polka dots","نقاط زخرفية"),EnglishAdvancedWord("packing paper","ورق تعبئة"),EnglishAdvancedWord("fragile item","شيء قابل للكسر"),EnglishAdvancedWord("sales counter","منضدة دفع"),EnglishAdvancedWord("craft seller","بائع حرف"),EnglishAdvancedWord("product label","ملصق منتج"),EnglishAdvancedWord("gift exchange","تبادل هدايا")],grammarTitle:"Going to for plans; will for decisions",grammarArabic:"نستخدم be going to لخطة قبل الكلام، وwill لقرار لحظي أو وعد: I am going to buy a gift. I will wrap it for you.",grammarExamples:<String>["I am going to buy a mug.","I will help wrap the present.","She is going to enjoy the surprise."],listening:"Welcome to the weekend craft fair. Most stalls close at six. If you want a handmade gift with initials, ask the seller before paying. Personalizing an item may take twenty extra minutes. Gift wrapping is available near the exit. Pack fragile ceramic pieces carefully, and keep the product label until you have checked the gift at home.",listeningQuestion:"What can take an extra twenty minutes?",listeningOptions:<String>["Personalizing a gift","Entering the fair","Buying water"],listeningAnswer:0,readingQuestion:"What made the mug personal?",readingOptions:<String>["His sister's initials were engraved","It was a plastic cup","The box was empty"],readingAnswer:0,writingCue:"The assistant tied a ____ around the gift box.",writingAnswer:"ribbon"),
    EnglishAdvancedLesson(level:"A2",unitNumber:2,number:10,title:"A Weekend by the Sea",titleArabic:"عطلة عند البحر",storyTitle:"A Weekend by the Sea",storyTitleArabic:"عطلة عند البحر",paragraphs:<String>["Amal and her cousins visited a quiet seaside village. They walked towards a lighthouse and watched the tide move across the rocks. A cool breeze made the coastline look beautiful.","After lunch, they spread a picnic blanket on the beach. Younger children built a sandcastle while Amal looked inside a rock pool and found a bright seashell. A lifeguard told them to avoid deep water.","Before sunset, they walked along the shore and photographed some fishing boats. Amal packed their food and promised to visit again next summer. Everyone enjoyed their peaceful day together."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("seaside village","قرية ساحلية"),EnglishAdvancedWord("lighthouse","منارة بحرية"),EnglishAdvancedWord("tide","مد وجزر"),EnglishAdvancedWord("rocks","صخور"),EnglishAdvancedWord("coastline","خط ساحلي"),EnglishAdvancedWord("picnic blanket","غطاء نزهة"),EnglishAdvancedWord("sandcastle","قلعة رملية"),EnglishAdvancedWord("rock pool","بركة صخرية"),EnglishAdvancedWord("seashell","صدفة بحرية"),EnglishAdvancedWord("lifeguard","منقذ سباحة"),EnglishAdvancedWord("shore","شاطئ"),EnglishAdvancedWord("fishing boats","قوارب صيد")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("beach umbrella","مظلة شاطئ"),EnglishAdvancedWord("swimming goggles","نظارات سباحة"),EnglishAdvancedWord("sand dunes","كثبان رملية"),EnglishAdvancedWord("beach towel","منشفة شاطئ"),EnglishAdvancedWord("low tide","الجزر"),EnglishAdvancedWord("high tide","المد"),EnglishAdvancedWord("coastal path","مسار ساحلي"),EnglishAdvancedWord("water shoes","حذاء مائي"),EnglishAdvancedWord("sea breeze","نسيم بحر"),EnglishAdvancedWord("tide table","جدول المد والجزر"),EnglishAdvancedWord("sun protection","واقي الشمس"),EnglishAdvancedWord("marine wildlife","حياة بحرية")],grammarTitle:"Used to for past routines",grammarArabic:"نستخدم used to + المصدر للعادة السابقة التي تغيرت: We used to visit every summer. وفي النفي didn't use to.",grammarExamples:<String>["We used to visit the beach every summer.","I didn't use to like cold water.","Did you use to collect seashells?"],listening:"Welcome to the seaside visitor center. Today's low tide begins at two fifteen, so visitors can explore the rock pools during the afternoon. Please wear suitable shoes and do not remove small sea animals. The lifeguard station closes at five. If you want to swim, stay inside the marked area and check the warning flags before entering the water.",listeningQuestion:"When is the best time to explore the rock pools?",listeningOptions:<String>["During the afternoon low tide","At midnight","Before the tide changes at dawn"],listeningAnswer:0,readingQuestion:"What did the lifeguard warn about?",readingOptions:<String>["Deep water","Buying souvenirs","Taking photographs"],readingAnswer:0,writingCue:"The children built a ____ on the beach.",writingAnswer:"sandcastle")
  ];
